function haversineDistance(lat1, lon1, lat2, lon2) {
  const R = 3959 // Earth radius in miles
  const toRad = (deg) => (deg * Math.PI) / 180
  const dLat = toRad(lat2 - lat1)
  const dLon = toRad(lon2 - lon1)
  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon / 2) * Math.sin(dLon / 2)
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a))
  return Math.round(R * c)
}

export function lookupAirport(iata) {
  if (!iata) return null
  const code = iata.trim().toUpperCase()
  const entry = AIRPORTS[code]
  if (!entry) return null
  return { iata: code, lat: entry[0], lng: entry[1], name: entry[2] }
}

export function calculateDistance(iata1, iata2) {
  const a = lookupAirport(iata1)
  const b = lookupAirport(iata2)
  if (!a || !b) return null
  return haversineDistance(a.lat, a.lng, b.lat, b.lng)
}

export function searchAirports(query) {
  if (!query || query.length < 2) return []
  const q = query.toUpperCase()
  const results = []
  for (const [code, entry] of Object.entries(AIRPORTS)) {
    if (code.startsWith(q) || entry[2].toUpperCase().includes(q)) {
      results.push({ iata: code, name: entry[2] })
    }
  }
  return results.slice(0, 8)
}
